import gymnasium as gym
from stable_baselines3 import PPO

# 1. Load the specific Environment with render_mode enabled
# "human" lets you see the window.
env = gym.make("LunarLander-v3", render_mode="human")

# 2. Load the trained model
# Change this path to the actual file generated by the previous script
model_path = "models/PPO/700000.zip" 

# Note: We don't need the GPU for inference (playing), CPU is fine here
model = PPO.load(model_path, env=env, device="cpu")

# 3. Play the game loop
episodes = 5

for ep in range(episodes):
    obs, info = env.reset()
    done = False
    truncated = False
    score = 0
    
    while not (done or truncated):
        # The model predicts the action based on the observation
        # deterministic=True means "do the absolute best move", no randomness
        action, _states = model.predict(obs, deterministic=True)
        
        # Take the action in the environment
        obs, reward, done, truncated, info = env.step(action)
        score += reward
        
    print(f"Episode {ep+1} Score: {score}")

env.close()